"""Browser UI for synchronized stereo grasp calibration."""

ARM_MAPPING_HTML = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>双摄抓取标定</title>
<style>
:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0b1320;color:#e9eef6;font-family:Arial,"Microsoft YaHei",sans-serif}.top{display:flex;gap:16px;align-items:center;padding:12px 16px;background:#111d2c;position:sticky;top:0;z-index:3}.top b,h3,a{color:#4fd1c5}.grid{display:grid;grid-template-columns:minmax(600px,1fr) 410px;gap:12px;padding:12px}.card{background:#111c2a;border:1px solid #33465d;border-radius:10px;padding:11px;margin-bottom:10px}.cams{display:grid;grid-template-columns:1fr 1fr;gap:8px}.stage{position:relative;background:#050a13;min-height:330px;display:flex;align-items:center;justify-content:center;overflow:hidden}.stage img{max-width:100%;max-height:58vh}.stage canvas{position:absolute;cursor:crosshair}.label{position:absolute;left:7px;top:7px;background:#111c2add;padding:3px 7px;color:#4fd1c5;z-index:2}.row{display:flex;gap:7px;flex-wrap:wrap;align-items:center;margin:8px 0}button,select,input,textarea{background:#172234;color:#edf2f7;border:1px solid #52677f;border-radius:6px;padding:8px}.go{background:#065f46}.blue{background:#1e3a5f}.bad{background:#6b1830}.active{outline:3px solid #facc15}.note{font-size:12px;color:#a9b8ca;line-height:1.55}.status{white-space:pre-wrap;font-size:12px;max-height:210px;overflow:auto;background:#0a111d;padding:8px}.metric{color:#facc15}.state{font-family:Consolas,monospace}.wide{width:100%}button:active{transform:translateY(2px);filter:brightness(1.35)}.ok{color:#34d399;font-weight:700}.offline{color:#fb7185;font-weight:700}.flow{margin:5px 0;padding-left:22px;line-height:1.75}@media(max-width:1050px){.grid{grid-template-columns:1fr}.cams{grid-template-columns:1fr}.stage{min-height:300px}}
</style></head><body>
<div class="top"><b>双摄抓取标定与中心→机械臂参数映射</b><span id="counts">加载中…</span><span id="bleStatus" class="offline">BLE检查中…</span><a href="/">返回抓取页</a><a href="/gripper-dataset">夹指数据页</a></div>
<div class="grid"><div><div class="card"><h3>操作流程</h3><ol class="flow"><li>确认顶部显示“BLE 已连接”。</li><li>保持“实时预览”，用右侧细步按钮调整机械臂。</li><li>到达可夹取位置后，点“同步拍摄左右图”冻结两幅照片。</li><li>点“Qwen目标 + YOLO夹指”，检查青色目标中心及红/蓝夹指点。</li><li>识别不准时先选“点目标中心/夹指”，再直接点击图像修正。</li><li>确认姿态可夹取后，点“确认保存（计数+1）”。</li></ol><div class="note">所有按钮的执行结果都会显示在右侧“操作信息”中。</div></div>
<div class="card"><div class="row"><label>物体名称 <input id="objectName" value="红色方块"></label><button onclick="liveView()">实时预览</button><button class="go" onclick="capturePair()">同步拍摄左右图</button><button onclick="analyze(true)">Qwen目标 + YOLO夹指</button><button onclick="analyze(false)">仅YOLO夹指</button></div>
<div class="cams"><div><div class="stage" id="stage-left"><span class="label">LEFT（车后向前看）</span><img id="img-left" src="/video/left"><canvas id="cv-left"></canvas></div><div class="row"><button onclick="mode('left','target')">点目标中心</button><button onclick="mode('left','jaw0')">点左夹指</button><button onclick="mode('left','jaw1')">点右夹指</button><span id="mode-left" class="note">目标中心</span></div></div>
<div><div class="stage" id="stage-right"><span class="label">RIGHT（车后向前看）</span><img id="img-right" src="/video/right"><canvas id="cv-right"></canvas></div><div class="row"><button onclick="mode('right','target')">点目标中心</button><button onclick="mode('right','jaw0')">点左夹指</button><button onclick="mode('right','jaw1')">点右夹指</button><span id="mode-right" class="note">目标中心</span></div></div></div>
<div class="note">青色框/十字=目标；黄色框=夹爪；红点和蓝点=两个夹指夹点。自动识别后可直接在对应画面点击修正。每次采集保存原始双摄照片，数量不设上限。</div></div>
<div class="card"><h3>保存当前可夹取姿态</h3><div class="row"><label><input id="graspReady" type="checkbox" checked> 当前姿态确实可夹取</label><label><input id="jawVerified" type="checkbox"> 已人工检查夹指点</label><label><input id="addJaw" type="checkbox" checked> 同时加入夹指YOLO数据</label></div><textarea id="notes" class="wide" placeholder="可选：光照、距离、是否有遮挡、抓取结果"></textarea><div class="row"><button class="go" onclick="saveSample()">确认保存（计数+1）</button></div></div>
</div><div>
<div class="card"><h3>细步控制（不影响自动进入视野）</h3><div class="row"><label>前后步长 <select id="stepForward"><option>1</option><option>2</option><option selected>5</option></select></label><button onclick="moveArm('forward',1)">前伸</button><button onclick="moveArm('forward',-1)">后退</button></div><div class="row"><label>上下步长 <select id="stepUp"><option>1</option><option>2</option><option selected>3</option></select></label><button onclick="moveArm('up',1)">上升</button><button onclick="moveArm('up',-1)">下降</button></div><div class="row"><label>左右步长 <select id="stepYaw"><option>1</option><option>2</option><option selected>3</option></select></label><button onclick="moveArm('yaw',1)">左移</button><button onclick="moveArm('yaw',-1)">右移</button></div><div class="row"><button onclick="rawArm('C90')">张开夹爪</button><button class="bad" onclick="rawArm('C2')">夹紧</button><button class="blue" onclick="rawArm('HOME')">归位</button><button onclick="baseline()">以当前位置为零点</button><button class="bad" onclick="rawArm('STOP')">停止</button></div><div id="armState" class="status state">状态加载中…</div><div class="note">设备没有舵机编码器；这里记录的是每条 BLE 命令积分后的 D/U、B/F、L/R 和 C 值。开机后请先归位；如果手工摆过机械臂，请在确定位置后点“以当前位置为零点”。</div></div>
<div class="card"><h3>训练物体中心映射</h3><div class="note">输入只用左右摄像头的目标中心及视差；夹指点不进入该回归模型，单独用于 YOLO-Pose。建议同一物体采集至少 20–30 个不同位置，越多越好，不设上限。</div><div class="row"><label>前后量化 <select id="qForward"><option>1</option><option>2</option><option selected>5</option></select></label><label>上下量化 <select id="qUp"><option>1</option><option>2</option><option selected>3</option></select></label><label>左右量化 <select id="qYaw"><option>1</option><option>2</option><option selected>3</option></select></label></div><div class="row"><button class="go" onclick="trainMap()">训练轻量映射</button><button onclick="predict()">用当前图片预测</button><a href="/api/arm-mapping/export"><button>下载全部数据ZIP</button></a></div><div id="model" class="status">尚未训练</div></div>
<div class="card"><h3>操作信息</h3><div id="msg" class="status metric">请先归位/标零，再同步拍摄。</div></div>
</div></div>
<script>
let S=null,V={left:null,right:null},M={left:'target',right:'target'};const E=id=>document.getElementById(id);
async function post(url,data){let r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data||{})});let j=await r.json();if(!r.ok||j.ok===false)throw Error(j.error||r.statusText);return j}
function say(x){E('msg').textContent=x}function mode(c,m){M[c]=m;document.getElementById('mode-'+c).textContent=m==='target'?'目标中心':(m==='jaw0'?'左夹指':'右夹指')}
function fit(c){let im=document.getElementById('img-'+c),cv=document.getElementById('cv-'+c),st=document.getElementById('stage-'+c),a=im.getBoundingClientRect(),b=st.getBoundingClientRect();cv.style.left=(a.left-b.left)+'px';cv.style.top=(a.top-b.top)+'px';cv.width=Math.round(a.width);cv.height=Math.round(a.height);draw(c)}
function xy(c,p){let v=V[c],cv=document.getElementById('cv-'+c);return{x:p.x*cv.width/v.width,y:p.y*cv.height/v.height}}
function rect(ctx,c,b,color,w){if(!b)return;let p=xy(c,{x:b.x1,y:b.y1}),q=xy(c,{x:b.x2,y:b.y2});ctx.strokeStyle=color;ctx.lineWidth=w;ctx.strokeRect(p.x,p.y,q.x-p.x,q.y-p.y)}
function dot(ctx,c,p,color,label){if(!p)return;let q=xy(c,p);ctx.fillStyle=color;ctx.beginPath();ctx.arc(q.x,q.y,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.fillText(label,q.x+8,q.y-7)}
function draw(c){let cv=document.getElementById('cv-'+c),ctx=cv.getContext('2d'),v=V[c];ctx.clearRect(0,0,cv.width,cv.height);if(!v)return;rect(ctx,c,v.target_bbox,'#22d3ee',3);rect(ctx,c,v.jaw_bbox,'#facc15',3);if(v.target_center){let q=xy(c,v.target_center);ctx.strokeStyle='#22d3ee';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(q.x-10,q.y);ctx.lineTo(q.x+10,q.y);ctx.moveTo(q.x,q.y-10);ctx.lineTo(q.x,q.y+10);ctx.stroke()}let k=v.jaw_points||[];dot(ctx,c,k[0],'#ef4444','L');dot(ctx,c,k[1],'#3b82f6','R')}
function liveView(){S=null;V={left:null,right:null};['left','right'].forEach(c=>{let im=document.getElementById('img-'+c);im.src='/video/'+c;im.onload=()=>fit(c)});say('实时预览中；调整到位后点同步拍摄左右图。')}
function showSample(meta){S=meta;V=meta.views;['left','right'].forEach(c=>{let im=document.getElementById('img-'+c);im.src='/api/arm-mapping/image/'+meta.sample_id+'/'+c+'?t='+Date.now();im.onload=()=>fit(c)});say('已拍摄 '+meta.sample_id+'，请自动分析或人工点击目标中心。')}
async function capturePair(){try{let j=await post('/api/arm-mapping/capture',{object_name:E('objectName').value,steps:{forward_mm:+E('stepForward').value,up_mm:+E('stepUp').value,yaw_deg:+E('stepYaw').value}});showSample(j.sample);refresh()}catch(e){say(e.message)}}
async function analyze(useQwen){if(!S)return say('请先同步拍摄');try{say(useQwen?'Qwen和YOLO分析中…':'YOLO夹指分析中…');let j=await post('/api/arm-mapping/analyze',{sample_id:S.sample_id,target_description:E('objectName').value,use_qwen:useQwen});S=j.sample;V=S.views;draw('left');draw('right');say('分析完成。请核对青色目标中心和红/蓝夹指点，可点击修正。')}catch(e){say(e.message)}}
['left','right'].forEach(c=>{document.getElementById('cv-'+c).onclick=e=>{if(!V[c])return;let cv=e.currentTarget,r=cv.getBoundingClientRect(),p={x:(e.clientX-r.left)*V[c].width/cv.width,y:(e.clientY-r.top)*V[c].height/cv.height},m=M[c];if(m==='target'){V[c].target_center=p;V[c].target_found=true}else{V[c].jaw_points=V[c].jaw_points||[];while(V[c].jaw_points.length<2)V[c].jaw_points.push({x:0,y:0,v:0});V[c].jaw_points[m==='jaw0'?0:1]={x:p.x,y:p.y,v:2,confidence:1}}draw(c)}})
async function saveSample(){if(!S)return say('请先同步拍摄');try{let j=await post('/api/arm-mapping/confirm',{sample_id:S.sample_id,views:V,grasp_ready:E('graspReady').checked,jaw_verified:E('jawVerified').checked,add_to_gripper_dataset:E('addJaw').checked,notes:E('notes').value});S=j.sample;V=S.views;say('保存成功：双摄抓取样本 +1'+(j.gripper_sample_ids&&Object.keys(j.gripper_sample_ids).length?'，夹指数据也已累计':'')+'。');refresh()}catch(e){say(e.message)}}
function stepId(axis){return E(axis==='forward'?'stepForward':axis==='up'?'stepUp':'stepYaw')}async function moveArm(axis,direction){let label={forward:['后退','前伸'],up:['下降','上升'],yaw:['右移','左移']}[axis][direction>0?1:0],step=+stepId(axis).value;say('正在发送：'+label+' '+step+'…');try{let j=await post('/api/arm/fine-move',{axis:axis,direction:direction,step:step});renderState(j.state);say('执行成功：'+label+' '+step+'，命令 '+j.command+'，BLE=OK')}catch(e){say('执行失败：'+e.message)}}
async function rawArm(ascii){say('正在发送：'+ascii+'…');try{let j=await post('/api/arm/raw',{ascii:ascii});await state();say(j.result==='OK'?'执行成功：'+ascii+'，BLE=OK':'执行失败：机械臂指令未写入，'+j.result)}catch(e){say('执行失败：'+e.message)}}async function baseline(){try{let j=await post('/api/arm/state/baseline',{});renderState(j.state);say('当前位置已设为参数零点。')}catch(e){say(e.message)}}
function renderState(s){E('armState').textContent='known='+s.known+'  forward='+s.forward_mm+'  up='+s.up_mm+'  yaw='+s.yaw_deg+'  claw='+s.claw_value+'\nlast='+s.last_command+'  seq='+s.sequence+'  reference='+s.reference}async function state(){try{let a=await fetch('/api/arm/state',{cache:'no-store'}).then(r=>r.json()),b=await fetch('/api/status',{cache:'no-store'}).then(r=>r.json());renderState(a.state);let e=E('bleStatus');e.textContent=b.ble?'BLE 已连接':'BLE 未连接';e.className=b.ble?'ok':'offline'}catch(e){}}
async function trainMap(){try{let j=await post('/api/arm-mapping/train',{object_name:E('objectName').value,quantization:{forward_mm:+E('qForward').value,up_mm:+E('qUp').value,yaw_deg:+E('qYaw').value}});E('model').textContent='样本 '+j.model.samples+'，测试 '+j.model.test_samples+'\nMAE '+JSON.stringify(j.model.test_mae)+'\n量化 '+JSON.stringify(j.model.quantization);say('训练完成；MAE 越小越好。')}catch(e){say(e.message)}}
async function predict(){if(!V)return say('请先拍摄并标出双摄目标中心');try{let j=await post('/api/arm-mapping/predict',{views:V});E('model').textContent='预测参数 '+JSON.stringify(j.prediction.parameters)+'\n原始值 '+JSON.stringify(j.prediction.raw_parameters)+'\n测试MAE '+JSON.stringify(j.prediction.test_mae)}catch(e){say(e.message)}}
async function refresh(){try{let j=await fetch('/api/arm-mapping/status',{cache:'no-store'}).then(r=>r.json());E('counts').textContent='双摄样本 '+j.status.samples+' · 可夹取 '+j.status.grasp_ready+' · 夹指已核 '+j.status.jaw_verified+'（无上限）';if(j.status.latest_model)E('model').textContent='当前模型：'+j.status.latest_model.object_name+' · '+j.status.latest_model.samples+'样本\nMAE '+JSON.stringify(j.status.latest_model.test_mae)}catch(e){}}window.onresize=()=>{fit('left');fit('right')};state();refresh();setInterval(state,2000);setInterval(refresh,5000);
</script></body></html>'''